-- =====================================================
-- PHÒNG KHÁM TƯ NHÂN - NHÓM 5
-- =====================================================
SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;

DROP DATABASE IF EXISTS phongkham_db;
CREATE DATABASE phongkham_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE phongkham_db;
SET NAMES utf8mb4;

-- ========== TV1: BÁC SĨ ==========
CREATE TABLE BacSi (
    ID INT AUTO_INCREMENT PRIMARY KEY,
    MaBS VARCHAR(5) UNIQUE NOT NULL,
    CMT VARCHAR(12) UNIQUE NOT NULL,
    HoTen VARCHAR(100) NOT NULL,
    GioiTinh ENUM('Nam', 'Nữ') NOT NULL,
    NgaySinh DATE NOT NULL,
    SDT VARCHAR(10) UNIQUE NOT NULL,
    Email VARCHAR(100) UNIQUE NOT NULL,
    DiaChi VARCHAR(255) NOT NULL,
    NgayVaoLam DATE NOT NULL,
    NgayNghiViec DATE,
    TrinhDo ENUM('Bác sĩ đa khoa', 'Bác sĩ nội trú', 'Bác sĩ Chuyên khoa I', 'Bác sĩ Chuyên Khoa II', 'Thạc sĩ', 'Tiến sĩ') NOT NULL,
    ChuyenMon VARCHAR(100),
    TrangThai ENUM('Đang làm việc', 'Đã nghỉ việc') DEFAULT 'Đang làm việc'
);

-- ========== TV2: Y TÁ + PHÂN CÔNG ==========
CREATE TABLE YTa (
    ID INT AUTO_INCREMENT PRIMARY KEY,
    MaNV VARCHAR(5) UNIQUE NOT NULL,
    CMT VARCHAR(12) UNIQUE NOT NULL,
    HoTen VARCHAR(100) NOT NULL,
    GioiTinh ENUM('Nam', 'Nữ') NOT NULL,
    NgaySinh DATE NOT NULL,
    SDT VARCHAR(10) UNIQUE NOT NULL,
    Email VARCHAR(100) UNIQUE NOT NULL,
    DiaChi VARCHAR(255) NOT NULL,
    NgayVaoLam DATE NOT NULL,
    NgayNghiViec DATE,
    TrinhDo ENUM('Trung cấp', 'Cao đẳng', 'Cử nhân', 'Đại học', 'Thạc sĩ', 'Tiến sĩ') NOT NULL,
    TrangThai ENUM('Đang làm việc', 'Đã nghỉ việc') DEFAULT 'Đang làm việc'
);

-- ========== TV3: BỆNH NHÂN + LẦN KHÁM ==========
CREATE TABLE BenhNhan (
    ID INT AUTO_INCREMENT PRIMARY KEY,
    MaBN VARCHAR(10) UNIQUE NOT NULL,
    CMT VARCHAR(12) UNIQUE NOT NULL,
    HoTen VARCHAR(100) NOT NULL,
    GioiTinh ENUM('Nam', 'Nữ') NOT NULL,
    NgaySinh DATE NOT NULL,
    SDT VARCHAR(10) UNIQUE NOT NULL,
    Email VARCHAR(100) UNIQUE NOT NULL,
    DiaChi VARCHAR(255) NOT NULL,
    NgayDangKy DATE NOT NULL
);

CREATE TABLE DanhMucBenh (
    MaBenh VARCHAR(10) PRIMARY KEY,
    TenBenh VARCHAR(100) NOT NULL,
    MoTa TEXT
);

CREATE TABLE LanKham (
    MaLanKham VARCHAR(15) PRIMARY KEY,
    MaBN VARCHAR(10) NOT NULL,
    MaBS VARCHAR(5) NOT NULL,
    MaBenh VARCHAR(10) NOT NULL,
    NgayVao DATE NOT NULL,
    NgayRa DATE,
    TongTienKham DECIMAL(12,0) DEFAULT 0,
    TrangThai VARCHAR(20) DEFAULT 'DangDieuTri',
    GhiChu TEXT,
    FOREIGN KEY (MaBN) REFERENCES BenhNhan(MaBN),
    FOREIGN KEY (MaBS) REFERENCES BacSi(MaBS),
    FOREIGN KEY (MaBenh) REFERENCES DanhMucBenh(MaBenh)
);

CREATE TABLE PhanCongYT (
    MaPC INT AUTO_INCREMENT PRIMARY KEY,
    MaLanKham VARCHAR(15) NOT NULL,
    MaNV VARCHAR(5) NOT NULL,
    NgayPhanCong DATE NOT NULL,
    LoaiHoTro VARCHAR(50) DEFAULT 'Chăm sóc người bệnh',
    FOREIGN KEY (MaLanKham) REFERENCES LanKham(MaLanKham),
    FOREIGN KEY (MaNV) REFERENCES YTa(MaNV)
);

-- ========== TV4: THUỐC + ĐƠN THUỐC ==========
CREATE TABLE Thuoc (
    MaThuoc VARCHAR(10) PRIMARY KEY,
    TenThuoc VARCHAR(100) NOT NULL,
    DonVi VARCHAR(20) DEFAULT 'Viên',
    GiaBan DECIMAL(12,0) NOT NULL,
    SoLuongTon INT DEFAULT 0
);

CREATE TABLE DonThuoc (
    MaDonThuoc VARCHAR(15) PRIMARY KEY,
    MaLanKham VARCHAR(15) NOT NULL,
    NgayKeDon DATE NOT NULL,
    FOREIGN KEY (MaLanKham) REFERENCES LanKham(MaLanKham)
);

CREATE TABLE ChiTietDonThuoc (
    MaDonThuoc VARCHAR(15),
    MaThuoc VARCHAR(10),
    SoLuong INT NOT NULL,
    DonGia DECIMAL(12,0) NOT NULL,
    ThanhTien DECIMAL(12,0) NOT NULL,
    PRIMARY KEY (MaDonThuoc, MaThuoc),
    FOREIGN KEY (MaDonThuoc) REFERENCES DonThuoc(MaDonThuoc),
    FOREIGN KEY (MaThuoc) REFERENCES Thuoc(MaThuoc)
);

-- ========== TV5: HÓA ĐƠN + THANH TOÁN + USER ==========
CREATE TABLE HoaDon (
    MaHoaDon VARCHAR(15) PRIMARY KEY,
    MaLanKham VARCHAR(15) NOT NULL,
    NgayLap DATETIME DEFAULT CURRENT_TIMESTAMP,
    TienKham DECIMAL(12,0) DEFAULT 0,
    TienThuoc DECIMAL(12,0) DEFAULT 0,
    TongTien DECIMAL(12,0) DEFAULT 0,
    TrangThai VARCHAR(20) DEFAULT 'ChuaThanhToan',
    NguoiLap VARCHAR(50),
    GhiChu TEXT,
    FOREIGN KEY (MaLanKham) REFERENCES LanKham(MaLanKham)
);

CREATE TABLE ThanhToan (
    MaThanhToan VARCHAR(15) PRIMARY KEY,
    MaHoaDon VARCHAR(15) NOT NULL,
    NgayThanhToan DATETIME DEFAULT CURRENT_TIMESTAMP,
    SoTien DECIMAL(12,0) NOT NULL,
    PhuongThuc VARCHAR(20) DEFAULT 'TienMat',
    NguoiThu VARCHAR(50),
    GhiChu TEXT,
    FOREIGN KEY (MaHoaDon) REFERENCES HoaDon(MaHoaDon)
);

CREATE TABLE NguoiDung (
    Username VARCHAR(50) PRIMARY KEY,
    MatKhau VARCHAR(50) NOT NULL,
    HoTen VARCHAR(100) NOT NULL,
    VaiTro VARCHAR(20) NOT NULL,
    TrangThai VARCHAR(20) DEFAULT 'Active'
);

-- Danh tính liên hệ dưới đây là dữ liệu mô phỏng; email dùng miền .test.




-- =====================================================
-- PROJECT 1: BỔ SUNG ĐỢT ĐIỀU TRỊ VÀ CÁC TRUY VẤN YÊU CẦU
-- Mở rộng schema để theo dõi đợt tái khám và chạy các truy vấn Project 1.
-- Mỗi đợt gồm một hoặc nhiều lần khám; tái phát sau khi khỏi tạo đợt mới.
-- =====================================================

CREATE TABLE DotDieuTri (
    MaDotDieuTri VARCHAR(20) PRIMARY KEY,
    MaBN VARCHAR(10) NOT NULL,
    MaBS VARCHAR(5) NOT NULL,
    MaBenh VARCHAR(10) NOT NULL,
    NgayBatDau DATE NOT NULL,
    NgayKetThuc DATE,
    TrangThai VARCHAR(20) NOT NULL DEFAULT 'DangDieuTri',
    FOREIGN KEY (MaBN) REFERENCES BenhNhan(MaBN),
    FOREIGN KEY (MaBS) REFERENCES BacSi(MaBS),
    FOREIGN KEY (MaBenh) REFERENCES DanhMucBenh(MaBenh)
);

ALTER TABLE LanKham
    ADD COLUMN MaDotDieuTri VARCHAR(20) NULL;

-- DỮ LIỆU MẪU TĨNH (cố định đến 13/11/2026). Các câu lệnh INSERT bên dưới
-- chứa sẵn từng bản ghi; không có procedure/vòng lặp sinh dữ liệu khi import.
-- Mỗi tháng đầy đủ có 45 bệnh nhân mới và 60 lượt khám; giá trị hóa đơn
-- được đặt theo gói khám chuyên sâu để phù hợp quy mô mô phỏng.
-- Phân công bác sĩ và y tá không đồng đều, luân phiên theo tháng để thể hiện
-- số ca và phụ cấp lương khác nhau giữa các nhân viên.
-- BenhNhan: 1575 bản ghi dữ liệu mẫu tĩnh.

-- LanKham: 2060 bản ghi dữ liệu mẫu tĩnh.

-- PhanCongYT: 2060 bản ghi dữ liệu mẫu tĩnh.

-- DonThuoc: 2060 bản ghi dữ liệu mẫu tĩnh.

-- ChiTietDonThuoc: 4120 bản ghi dữ liệu mẫu tĩnh.

-- HoaDon: 2060 bản ghi dữ liệu mẫu tĩnh.

-- ThanhToan: 2060 bản ghi dữ liệu mẫu tĩnh.

-- Backfill dữ liệu cũ: mỗi lần khám hiện có được gán một đợt riêng.
-- Từ các lần nhập mới, các lần tái khám liên tiếp cần dùng chung mã đợt.
SELECT CONCAT('DT', lk.MaLanKham), lk.MaBN, lk.MaBS, lk.MaBenh, lk.NgayVao,
       CASE WHEN lk.TrangThai='DaKhoi' THEN COALESCE(lk.NgayRa, lk.NgayVao) ELSE NULL END,
       lk.TrangThai
FROM LanKham lk;

UPDATE LanKham
SET MaDotDieuTri=CONCAT('DT', MaLanKham)
WHERE MaLanKham > '' AND MaDotDieuTri IS NULL;

ALTER TABLE LanKham
    MODIFY MaDotDieuTri VARCHAR(20) NOT NULL,
    ADD CONSTRAINT fk_LanKham_DotDieuTri
        FOREIGN KEY (MaDotDieuTri) REFERENCES DotDieuTri(MaDotDieuTri);

CREATE OR REPLACE VIEW V_DotDieuTri AS
SELECT d.MaDotDieuTri, d.MaBN, bn.HoTen AS TenBN, d.MaBS, bs.HoTen AS TenBS,
       d.MaBenh, dm.TenBenh, d.NgayBatDau, d.NgayKetThuc, d.TrangThai,
       COUNT(lk.MaLanKham) AS SoLanKham
FROM DotDieuTri d
JOIN BenhNhan bn ON bn.MaBN=d.MaBN
JOIN BacSi bs ON bs.MaBS=d.MaBS
JOIN DanhMucBenh dm ON dm.MaBenh=d.MaBenh
LEFT JOIN LanKham lk ON lk.MaDotDieuTri=d.MaDotDieuTri
GROUP BY d.MaDotDieuTri, d.MaBN, bn.HoTen, d.MaBS, bs.HoTen,
         d.MaBenh, dm.TenBenh, d.NgayBatDau, d.NgayKetThuc, d.TrangThai;

CREATE OR REPLACE VIEW V_HoSoBenhNhan AS
SELECT lk.MaBN, bn.HoTen AS TenBN, lk.MaLanKham, lk.MaDotDieuTri,
       lk.MaBenh, dm.TenBenh, lk.MaBS, bs.HoTen AS TenBS,
       lk.NgayVao, lk.NgayRa, lk.TongTienKham, lk.TrangThai,
       d.TrangThai AS TrangThaiDot,
       (SELECT COUNT(*) + 1
        FROM LanKham truoc
        WHERE truoc.MaDotDieuTri=lk.MaDotDieuTri
          AND (truoc.NgayVao < lk.NgayVao
               OR (truoc.NgayVao=lk.NgayVao AND truoc.MaLanKham < lk.MaLanKham))
       ) AS LanThuTrongDot,
       (SELECT COUNT(*)
        FROM LanKham cungBenh
        WHERE cungBenh.MaBN=lk.MaBN AND cungBenh.MaBenh=lk.MaBenh
       ) AS TongLanKhamBenh,
       (SELECT GROUP_CONCAT(CONCAT(t.TenThuoc, ' x', ct.SoLuong)
                            ORDER BY t.TenThuoc SEPARATOR ', ')
        FROM DonThuoc dt
        JOIN ChiTietDonThuoc ct ON ct.MaDonThuoc=dt.MaDonThuoc
        JOIN Thuoc t ON t.MaThuoc=ct.MaThuoc
        WHERE dt.MaLanKham=lk.MaLanKham
       ) AS ThuocKe,
       COALESCE((SELECT SUM(ct.ThanhTien)
                 FROM DonThuoc dt
                 JOIN ChiTietDonThuoc ct ON ct.MaDonThuoc=dt.MaDonThuoc
                 WHERE dt.MaLanKham=lk.MaLanKham),0) AS TongTienThuoc,
       (SELECT GROUP_CONCAT(CONCAT(y.HoTen, ': ', pc.LoaiHoTro)
                            ORDER BY y.HoTen SEPARATOR '; ')
        FROM PhanCongYT pc
        JOIN YTa y ON y.MaNV=pc.MaNV
        WHERE pc.MaLanKham=lk.MaLanKham
       ) AS HoTroYTa
FROM LanKham lk
JOIN BenhNhan bn ON bn.MaBN=lk.MaBN
JOIN DanhMucBenh dm ON dm.MaBenh=lk.MaBenh
JOIN BacSi bs ON bs.MaBS=lk.MaBS
JOIN DotDieuTri d ON d.MaDotDieuTri=lk.MaDotDieuTri;

CREATE OR REPLACE VIEW V_LuotHoTroYTa AS
SELECT pc.MaPC, pc.MaNV, y.HoTen AS TenYT, pc.MaLanKham, lk.MaBN,
       pc.NgayPhanCong, pc.LoaiHoTro
FROM PhanCongYT pc
JOIN YTa y ON y.MaNV=pc.MaNV
JOIN LanKham lk ON lk.MaLanKham=pc.MaLanKham;

CREATE OR REPLACE VIEW V_DoanhThuHoaDon AS
SELECT hd.MaHoaDon, hd.MaLanKham, lk.MaBN, bn.HoTen AS TenBN,
       lk.MaBS, bs.HoTen AS TenBS, hd.NgayLap, hd.TienKham, hd.TienThuoc,
       hd.TongTien, hd.TrangThai
FROM HoaDon hd
JOIN LanKham lk ON lk.MaLanKham=hd.MaLanKham
JOIN BenhNhan bn ON bn.MaBN=lk.MaBN
JOIN BacSi bs ON bs.MaBS=lk.MaBS
WHERE hd.TrangThai NOT IN ('Huy', 'Đã Hủy');

-- CÂU TRUY VẤN PROJECT 1
-- Thay @NgayTu và @NgayDen nếu cần xem một tháng khác.
SET @NgayTu = DATE_FORMAT(CURDATE(), '%Y-%m-01');
SET @NgayDen = CURDATE();
SET @MaBN = NULL; -- Nhập mã bệnh nhân cần tra cứu, ví dụ: 'BN000001'.

-- 1. Thống kê bệnh theo số đợt mắc trong kỳ.
-- Nhiều lần khám cùng MaDotDieuTri được tính là một đợt;
-- tái phát sau khi khỏi có MaDotDieuTri mới nên được tính thêm.
SELECT d.MaBenh, d.TenBenh,
       COUNT(DISTINCT d.MaDotDieuTri) AS SoDotMac,
       COUNT(DISTINCT d.MaBN) AS SoBenhNhan
FROM V_DotDieuTri d
JOIN LanKham lk ON lk.MaDotDieuTri=d.MaDotDieuTri
WHERE lk.NgayVao >= @NgayTu
  AND lk.NgayVao < DATE_ADD(@NgayDen, INTERVAL 1 DAY)
GROUP BY d.MaBenh, d.TenBenh
ORDER BY SoDotMac DESC, SoBenhNhan DESC, d.TenBenh;

-- 2a. Lương bác sĩ: 7 triệu + 1 triệu cho mỗi đợt đã khỏi trong kỳ.
SELECT bs.MaBS, bs.HoTen, 7000000 AS LuongCoBan,
       COUNT(d.MaDotDieuTri) AS SoDotKhoi,
       7000000 + COUNT(d.MaDotDieuTri)*1000000 AS TongLuong
FROM BacSi bs
LEFT JOIN V_DotDieuTri d
       ON d.MaBS=bs.MaBS
      AND d.TrangThai='DaKhoi'
      AND d.NgayKetThuc >= @NgayTu
      AND d.NgayKetThuc < DATE_ADD(@NgayDen, INTERVAL 1 DAY)
WHERE bs.NgayVaoLam < DATE_ADD(@NgayDen, INTERVAL 1 DAY)
  AND (bs.NgayNghiViec IS NULL OR bs.NgayNghiViec >= @NgayTu)
GROUP BY bs.MaBS, bs.HoTen
ORDER BY bs.MaBS;

-- 2b. Lương y tá: 5 triệu + 200 nghìn cho mỗi lượt hỗ trợ trong kỳ.
SELECT y.MaNV, y.HoTen, 5000000 AS LuongCoBan,
       COUNT(pc.MaPC) AS SoLuotHoTro,
       5000000 + COUNT(pc.MaPC)*200000 AS TongLuong
FROM YTa y
LEFT JOIN V_LuotHoTroYTa pc
       ON pc.MaNV=y.MaNV
      AND pc.NgayPhanCong >= @NgayTu
      AND pc.NgayPhanCong < DATE_ADD(@NgayDen, INTERVAL 1 DAY)
GROUP BY y.MaNV, y.HoTen
ORDER BY y.MaNV;

-- 3a. Lịch sử khám và điều trị của một bệnh nhân.
SELECT MaBN, TenBN, MaLanKham, MaDotDieuTri, TenBenh,
       LanThuTrongDot, TongLanKhamBenh, TenBS, NgayVao, NgayRa,
       ThuocKe, TongTienKham, TongTienThuoc, HoTroYTa, TrangThai, TrangThaiDot
FROM V_HoSoBenhNhan
WHERE MaBN=@MaBN
ORDER BY NgayVao, MaLanKham;

-- 3b. Những bệnh/đợt điều trị bệnh nhân đang mắc tại thời điểm truy vấn.
SELECT MaBN, TenBN, MaDotDieuTri, TenBenh, NgayBatDau, SoLanKham
FROM V_DotDieuTri
WHERE MaBN=@MaBN AND TrangThai='DangDieuTri'
ORDER BY NgayBatDau;

-- 4. Doanh thu theo hóa đơn trong kỳ, gồm tiền khám và tiền thuốc.
SELECT COALESCE(SUM(TienKham),0) AS TongTienKham,
       COALESCE(SUM(TienThuoc),0) AS TongTienThuoc,
       COALESCE(SUM(TongTien),0) AS TongDoanhThu,
       COUNT(*) AS SoHoaDon
FROM V_DoanhThuHoaDon
WHERE NgayLap >= @NgayTu
  AND NgayLap < DATE_ADD(@NgayDen, INTERVAL 1 DAY);

SELECT '=== TRUY VẤN PROJECT 1 SẴN SÀNG ===' AS msg;
SHOW TABLES;


SELECT '=== DATABASE AND STATIC SAMPLE DATA READY ===' AS msg;
SELECT COUNT(*) AS TongBacSi FROM BacSi;
SELECT COUNT(*) AS TongYTa FROM YTa;
SELECT COUNT(*) AS TongBenhNhan FROM BenhNhan;
SELECT COUNT(*) AS TongLuotKham FROM LanKham;
SELECT DATE_FORMAT(NgayDangKy,'%Y-%m') AS Thang,
       COUNT(*) AS SoBenhNhanMoi
FROM BenhNhan
GROUP BY DATE_FORMAT(NgayDangKy,'%Y-%m')
ORDER BY Thang;
SELECT DATE_FORMAT(NgayLap,'%Y-%m') AS Thang,
       COUNT(*) AS SoHoaDon,
       ROUND(SUM(TongTien) / 1000000, 1) AS DoanhThuTrieuDong
FROM HoaDon
WHERE TrangThai NOT IN ('Huy','Đã Hủy')
GROUP BY DATE_FORMAT(NgayLap,'%Y-%m')
ORDER BY Thang;
